      "シェーンバイン法は、シアン化物から発生するシアン化水素を検出する試験で、グアヤク試験紙が青色に変化することが特徴です。メッキ工場ではシアン化カリウムなどのシアン化物が使用されることがあり、摂取直後の頭痛、悪心、嘔吐、頻脈などもシアン中毒でみられます。したがって、疑われる物質は4のシアン化カリウムです。\nヒ素は重い消化器症状などを起こしますが、シェーンバイン法の所見とは結びつきません。トルエンやn-ヘキサンは主に有機溶剤中毒で、中枢神経症状や末梢神経障害が問題になります。ジクロルボスは有機リン系殺虫剤で、縮瞳、流涎、発汗などのコリン作動性症状が典型的です。"
