      "20歳男性。8月上旬に友人と海水浴に行くことになり、日焼け止めについて相談するため、薬局を訪れた。男性は前年の同時期に海水浴へ行き、日中、炎天下の浜辺で過ごした。その日の夕方から、昼に露出していた肌が赤くなり、その部分にほてりやヒリヒリとした痛みを感じ、その後、水ぶくれができた。男性は、最近数年間、内服薬や外用薬などの使用はなく、これまで日焼け止めを使用したことはなかった。\n\n下図は、波長に基づく非電離放射線の分類を示している。海水浴でこの男性の肌に生じた症状の原因となる主な非電離放射線はどれか。1つ選べ。",

