    question:
      "その後、てんかんの痙れん発作が起こったためフェニトイン散10%の投与量を1日3.5 g（フェニトインとして350 mg/day）に増量したところ、C_ss は20 μg/mLとなった。フェニトインの代謝速度はミカエリス・メンテン（Michaelis–Menten）式に従うものとすると、この患者におけるミカエリス定数（K_m）と最大消失速度（V_max）に最も近い値の組合せはどれか。1つ選べ。\nただし、フェニトインは主に肝代謝により消失し、定常状態における消失速度は代謝速度に等しいと仮定する。また、フェニトインのバイオアベイラビリティは100%とし、てんかんの発作前後ではK_mとV_maxは変化しないものとする。",

