    "心筋梗塞後の心室性不整脈を抑制する目的で、アムロジピンが処方されている。",
    "心筋梗塞後の胸痛を緩和する目的で、アスピリンが処方されている。",
    "薬剤性消化性潰瘍を防止する目的で、ラベプラゾールが処方されている。",
