    sourceType: "past_exam",
    examNumber: 108,
    sourceNumber: 310,
    caseId: "108-310-311",
    caseContext:
      "75歳男性。糖尿病及び糖尿病性腎症で在宅療養にて腹膜透析を行い、薬物治療中である。今回、処方1及び処方2が追加された処方箋が発行された。過去の薬歴から処方1及び処方2は初めて処方されたことがわかった。薬剤師が、調剤した薬剤を持って患者宅を訪問した。\n\n（処方1）\nダルベポエチン　アルファ（遺伝子組換え）注射液 30 μg プラシリンジ\n1回1本\n皮下注射　2週間に1回　全2回分\n※自己注射ではありません。\n\n（処方2）\nクエン酸第一鉄ナトリウム錠 50 mg　1回2錠（1日4錠）\n1日2回　朝夕食後　28日分\n\n（直近の検査値）\n白血球 6,500/μL、赤血球 284×10^4/μL、Hb 8.6 g/dL、Ht 26%、MCV 91.5 fL、MCH 30.3 pg、MCHC 33.1%、血小板 22.3×10^4/μL、eGFR 8.9 mL/min/1.73 m^2、血清鉄 45 μg/dL（基準値 54〜200 μg/dL（男性））、血清ビタミンB12値と血清葉酸値は基準値内",
    field: "実務",

    question:
      "処方1、処方2の説明として、適切なのはどれか。2つ選べ。",

