      "30歳男性。喫煙歴10年。1週間前から禁煙を決意し、自分でたばこをやめてみた。しかし、このまま禁煙が続けられるのか不安があり、薬局を訪れて薬剤師に相談した。\n男性：禁煙に関して相談してもよろしいですか。\n薬剤師：なんでもどうぞ。\n男性：実は、1週間前にたばこをやめてから、ここ数日イライラしてしまって、禁煙をこのまま続けられるか不安です。\n薬剤師：1週間禁煙は続けられたけれども、これからも続けられるのか不安なのですね。",
