      "86歳女性。誤嚥性肺炎で入院し、栄養障害もあったため経鼻経管栄養を実施し退院した。本人の希望により娘の介助のもとで在宅にて療養をしている。薬局薬剤師が在宅訪問を行うにあたり、介護支援専門員から、「本人より、経管栄養をやめてほしいという要望がある。」と報告された。一方、在宅訪問の際、家族からは「なんとか元気になってほしいので、経管栄養を続けてほしい。」との意向を聴取した。",
