    caseContext:
      "45歳女性。調理師。仕事中に動悸を感じていたが、疲れのためだろうと深刻に考えていなかった。健康診断で不整脈の疑いが指摘されたため、近隣の診療所を受診したところ、頻脈傾向で処方1が処方され薬局Aで調剤された。1週間後、診療所から紹介された医療機関を受診し、精査したところ、肝機能及び腎機能は正常値であったものの、心房細動と確定診断されたため、新たに処方2が追加された。この患者が処方2の処方箋を持参して、薬局Bに来局した。患者からの聞き取りで、処方1の薬を服用していることが確認できたが、お薬手帳には過去の治療薬の記載のみで、処方1の薬の記載はなかった。また、患者は、セントジョーンズワート含有食品を常用していると話していた。処方1開始時の血圧143/86 mmHg、脈拍98回/分。\n\n（処方1）\nビソプロロールフマル酸塩錠2.5 mg　1回1錠（1日1錠）　1日1回　朝食後　14日分\n\n（処方2）\nリバーロキサバン錠15 mg　1回1錠（1日1錠）　1日1回　朝食後　14日分",
