    "職業が調理師であるため包丁の使用などでの出血に注意するように説明したが、職業は個人情報であるため薬歴には記載しなかった。",
    "リバーロキサバンに注意が必要なビタミンK含有量の多いブロッコリーなどの食品の過剰摂取がないか確認した。",
    "処方1について薬局Aに確認し、薬歴に記録を残しお薬手帳にも併用薬情報として記載した。"
